import { validateTokenizedPayment } from './validator';
import { processPayment } from '../payment/processor';

export class TokenizationService {
  async tokenizePayment(rawPaymentData: any): Promise<any> {
    // This is a simplified version - actual implementation would be more complex

    // Validate the tokenized payment
    const clock = {
      getCurrentYear: () => new Date().getFullYear()
    };

    const validation = validateTokenizedPayment(rawPaymentData, clock);

    if (!validation.valid) {
      throw new Error(`Invalid tokenized payment: ${validation.errors.join(', ')}`);
    }

    // Process the payment
    return await processPayment(rawPaymentData);
  }
}

