 * Tokenized Payment Payload Validator
 *
 * Validates payloads for card-tokenization integration.
 * This validator performs structural and semantic checks but does NOT
 * imply PCI compliance of the broader system.
 */

export interface Clock {
  getCurrentYear: () => number;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

// --- Reusable primitive validators ---

function isString(value: unknown): value is string {
  return typeof value === 'string';
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value) && isFinite(value);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isValidUuid(uuid: string): boolean {
  return UUID_REGEX.test(uuid);
}

const TOKEN_REGEX = /^tok_[a-zA-Z0-9]{16,32}$/;

function isValidToken(token: string): boolean {
  return TOKEN_REGEX.test(token);
}

const IDEMPOTENCY_KEY_REGEX = /^[a-zA-Z0-9-]+$/;

function isValidIdempotencyKey(key: string): boolean {
  return key.length >= 16 && key.length <= 64 && IDEMPOTENCY_KEY_REGEX.test(key);
}

function isValidLast4(last4: string): boolean {
  return last4.length === 4 && /^\d{4}$/.test(last4);
}

const SUPPORTED_BRANDS = new Set(['visa', 'mastercard', 'amex', 'discover']);

function isValidBrand(brand: string): boolean {
  return SUPPORTED_BRANDS.has(brand);
}

function isValidExpMonth(month: number): boolean {
  return Number.isInteger(month) && month >= 1 && month <= 12;
}

function isValidExpYear(year: number, clock: Clock): boolean {
  return Number.isInteger(year) && year >= clock.getCurrentYear();
}

function isValidCountry(country: string): boolean {
  // ISO 3166-1 alpha-2: exactly 2 letters
  return country.length === 2 && /^[a-zA-Z]{2}$/.test(country);
}

function isValidUsState(state: string): boolean {
  return state.length === 2 && /^[a-zA-Z]{2}$/.test(state);
}

function isValidUsPostalCode(postalCode: string): boolean {
  return /^\d{5}$/.test(postalCode) || /^\d{5}-\d{4}$/.test(postalCode);
}

function isValidNonUsState(state: string): boolean {
  return state.length === 0 || state.length <= 32;
}

function isValidNonUsPostalCode(postalCode: string): boolean {
  return postalCode.length >= 2 && postalCode.length <= 10 && /^[a-zA-Z0-9]+$/.test(postalCode);
}

// --- PAN / CVV detection ---

/**
 * Detects raw PAN (13-19 consecutive digits) or CVV/CVC (3-4 consecutive digits
 * that look like security codes). We scan string values recursively.
 */
function containsSensitiveCardData(value: string): boolean {
  // PAN: 13-19 consecutive digits
  const panRegex = /\b\d{13,19}\b/;
  // CVV/CVC: 3-4 consecutive digits (heuristic)
  const cvvRegex = /\b\d{3,4}\b/;

  if (panRegex.test(value)) {
    return true;
  }

  // For CVV we only flag if the string is short (standalone CVV field)
  // to avoid flagging every number in addresses etc.
  if (value.length <= 4 && cvvRegex.test(value)) {
    return true;
  }

  return false;
}

/**
 * Recursively scan the payload for sensitive card data in any string field.
 */
function scanForSensitiveData(
  obj: unknown,
  path: string,
  errors: string[]
): void {
  if (isString(obj)) {
    if (containsSensitiveCardData(obj)) {
      errors.push(`${path}: contains sensitive card data`);
    }
    return;
  }

  if (Array.isArray(obj)) {
    obj.forEach((item, index) => {
      scanForSensitiveData(item, `${path}[${index}]`, errors);
    });
    return;
  }

  if (isPlainObject(obj)) {
    for (const [key, value] of Object.entries(obj)) {
      const fieldPath = path ? `${path}.${key}` : key;
      scanForSensitiveData(value, fieldPath, errors);
    }
    return;
  }

  // Primitives other than strings are safe
}

// --- Structural validators ---

function validateRequiredString(
  value: unknown,
  fieldPath: string,
  errors: string[]
): string | undefined {
  if (!isString(value)) {
    errors.push(`${fieldPath}: must be a string`);
    return undefined;
  }
  if (value.length === 0) {
    errors.push(`${fieldPath}: required`);
    return undefined;
  }
  return value;
}

function validateRequiredNumber(
  value: unknown,
  fieldPath: string,
  errors: string[]
): number | undefined {
  if (!isNumber(value)) {
    errors.push(`${fieldPath}: must be a number`);
    return undefined;
  }
  return value;
}

function validateRequiredObject(
  value: unknown,
  fieldPath: string,
  errors: string[]
): Record<string, unknown> | undefined {
  if (!isPlainObject(value)) {
    errors.push(`${fieldPath}: must be an object`);
    return undefined;
  }
  return value;
}

// --- Cross-field validators ---

function validatePaymentMethod(
  paymentMethod: Record<string, unknown>,
  errors: string[]
): void {
  const token = validateRequiredString(paymentMethod.token, 'payment_method.token', errors);
  if (token !== undefined && !isValidToken(token)) {
    errors.push('payment_method.token: invalid format');
  }

  const brand = validateRequiredString(paymentMethod.brand, 'payment_method.brand', errors);
  if (brand !== undefined && !isValidBrand(brand)) {
    errors.push('payment_method.brand: unsupported brand');
  }

  const last4 = validateRequiredString(paymentMethod.last4, 'payment_method.last4', errors);
  if (last4 !== undefined && !isValidLast4(last4)) {
    errors.push('payment_method.last4: must be exactly 4 digits');
  }

  const expMonth = validateRequiredNumber(paymentMethod.exp_month, 'payment_method.exp_month', errors);
  if (expMonth !== undefined && !isValidExpMonth(expMonth)) {
    errors.push('payment_method.exp_month: must be between 1 and 12');
  }

  const expYear = validateRequiredNumber(paymentMethod.exp_year, 'payment_method.exp_year', errors);
  if (expYear !== undefined && !isValidExpYear(expYear, { getCurrentYear: () => new Date().getFullYear() })) {
    // We'll re-check with injectable clock in the main function
  }

  // Reject extra fields on payment_method
  const allowedKeys = new Set(['token', 'brand', 'last4', 'exp_month', 'exp_year']);
  for (const key of Object.keys(paymentMethod)) {
    if (!allowedKeys.has(key)) {
      errors.push(`payment_method.${key}: unexpected field`);
    }
  }
}

function validateBillingAddress(
  address: Record<string, unknown>,
  errors: string[]
): void {
  validateRequiredString(address.name, 'billing_address.name', errors);
  validateRequiredString(address.line1, 'billing_address.line1', errors);

  // line2 is optional
  if (address.line2 !== undefined && !isString(address.line2)) {
    errors.push('billing_address.line2: must be a string');
  }

  validateRequiredString(address.city, 'billing_address.city', errors);

  const state = validateRequiredString(address.state, 'billing_address.state', errors);
  const country = validateRequiredString(address.country, 'billing_address.country', errors);
  const postalCode = validateRequiredString(address.postal_code, 'billing_address.postal_code', errors);

  if (country !== undefined) {
    if (!isValidCountry(country)) {
      errors.push('billing_address.country: invalid ISO 3166-1 alpha-2 format');
    } else {
      const countryUpper = country.toUpperCase();

      if (state !== undefined) {
        if (countryUpper === 'US') {
          if (!isValidUsState(state)) {
            errors.push('billing_address.state: must be a 2-letter code for US addresses');
          }
        } else {
          if (!isValidNonUsState(state)) {
            errors.push('billing_address.state: must be empty or up to 32 characters for non-US addresses');
          }
        }
      }

      if (postalCode !== undefined) {
        if (countryUpper === 'US') {
          if (!isValidUsPostalCode(postalCode)) {
            errors.push('billing_address.postal_code: invalid US postal code format');
          }
        } else {
          if (!isValidNonUsPostalCode(postalCode)) {
            errors.push('billing_address.postal_code: invalid postal code format for non-US address');
          }
        }
      }
    }
  }

  // Reject extra fields on billing_address
  const allowedKeys = new Set(['name', 'line1', 'line2', 'city', 'state', 'postal_code', 'country']);
  for (const key of Object.keys(address)) {
    if (!allowedKeys.has(key)) {
      errors.push(`billing_address.${key}: unexpected field`);
    }
  }
}

function validateMetadata(
  metadata: unknown,
  fieldPath: string,
  errors: string[]
): void {
  if (metadata === undefined) {
    return;
  }

  if (!isPlainObject(metadata)) {
    errors.push(`${fieldPath}: must be an object`);
    return;
  }

  const entries = Object.entries(metadata);
  if (entries.length > 20) {
    errors.push(`${fieldPath}: must not exceed 20 entries`);
  }

  for (const [key, value] of entries) {
    if (!isString(value)) {
      errors.push(`${fieldPath}.${key}: value must be a string`);
    } else if (value.length > 500) {
      errors.push(`${fieldPath}.${key}: value must not exceed 500 characters`);
    }
  }
}

// --- Main entry point ---

export function validateTokenizedPayment(
  payload: unknown,
  clock: Clock
): ValidationResult {
  const errors: string[] = [];

  // 1. Payload must be an object
  if (!isPlainObject(payload)) {
    return { valid: false, errors: ['payload: must be an object'] };
  }

  // 2. Scan for sensitive card data first (PAN/CVV) anywhere in payload
  scanForSensitiveData(payload, '', errors);

  // 3. Structural validation of top-level fields
  const requestId = validateRequiredString(payload.request_id, 'request_id', errors);
  if (requestId !== undefined && !isValidUuid(requestId)) {
    errors.push('request_id: invalid UUID format');
  }

  const merchantId = validateRequiredString(payload.merchant_id, 'merchant_id', errors);
  if (merchantId !== undefined && !isValidUuid(merchantId)) {
    errors.push('merchant_id: invalid UUID format');
  }

  const idempotencyKey = validateRequiredString(payload.idempotency_key, 'idempotency_key', errors);
  if (idempotencyKey !== undefined && !isValidIdempotencyKey(idempotencyKey)) {
    errors.push('idempotency_key: must be 16-64 alphanumeric or hyphen characters');
  }

  const paymentMethod = validateRequiredObject(payload.payment_method, 'payment_method', errors);
  if (paymentMethod !== undefined) {
    validatePaymentMethod(paymentMethod, errors);

    // Cross-field: exp_year must be current or future (requires injectable clock)
    const expYear = paymentMethod.exp_year;
    if (isNumber(expYear) && !isValidExpYear(expYear, clock)) {
      errors.push('payment_method.exp_year: must be current year or future');
    }
  }

  const billingAddress = validateRequiredObject(payload.billing_address, 'billing_address', errors);
  if (billingAddress !== undefined) {
    validateBillingAddress(billingAddress, errors);
  }

  validateMetadata(payload.metadata, 'metadata', errors);

  // 4. Reject extra top-level fields
  const allowedTopLevelKeys = new Set([
    'request_id',
    'merchant_id',
    'idempotency_key',
    'payment_method',
    'billing_address',
    'metadata',
  ]);
  for (const key of Object.keys(payload)) {
    if (!allowedTopLevelKeys.has(key)) {
      errors.push(`${key}: unexpected field`);
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}
"})

