```typescript
/**
 * Tokenized Payment Validator
 *
 * Validates payloads for card-tokenization integration.
 *
 * IMPORTANT: This validator performs format and content validation for tokenized
 * payment payloads. It is one component of a broader PCI DSS compliance strategy
 * and does not alone make the system PCI compliant.
 */

import { isValidUuid, isValidAlphanumericHyphen } from '../utils/validation';

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export interface Clock {
  getCurrentYear: () => number;
}

// Fields that are allowed to contain short numeric sequences
const SAFE_SHORT_NUMERIC_FIELDS = new Set([
  'payment_method.last4',
  'billing_address.postal_code',
]);

const VALID_CARD_BRANDS = ['visa', 'mastercard', 'amex', 'discover'];
const ALLOWED_TOP_LEVEL_FIELDS = [
  'request_id',
  'merchant_id',
  'idempotency_key',
  'payment_method',
  'billing_address',
  'metadata',
];
const ALLOWED_PAYMENT_METHOD_FIELDS = ['token', 'brand', 'last4', 'exp_month', 'exp_year'];
const ALLOWED_ADDRESS_FIELDS = ['name', 'line1', 'line2', 'city', 'state', 'postal_code', 'country'];

// --- Format validators ---

function isValidPrefixedUuid(value: string): boolean {
  if (isValidUuid(value)) {
    return true;
  }
  // Support prefixed IDs like req_<uuid> or merch_<uuid>
  const parts = value.split('_');
  if (parts.length >= 2) {
    return isValidUuid(parts[parts.length - 1]);
  }
  return false;
}

function isValidToken(token: string): boolean {
  return /^tok_[a-zA-Z0-9]{16,32}$/.test(token);
}

function isValidLast4(last4: string): boolean {
  return /^\d{4}$/.test(last4);
}

function isValidIdempotencyKey(key: string): boolean {
  return key.length >= 16 && key.length <= 64 && isValidAlphanumericHyphen(key);
}

function isValidUsState(state: string): boolean {
  return /^[A-Z]{2}$/.test(state);
}

function isValidUsPostalCode(postalCode: string): boolean {
  return /^\d{5}(-\d{4})?$/.test(postalCode);
}

function isValidNonUsPostalCode(postalCode: string): boolean {
  return /^[a-zA-Z0-9]{2,10}$/.test(postalCode);
}

function isValidCountryCode(country: string): boolean {
  return /^[A-Z]{2}$/.test(country);
}

// --- Sensitive data detection ---

function containsPan(value: string): boolean {
  // Detect unbroken sequences of 13-19 digits (standard PAN lengths)
  if (/\d{13,19}/.test(value)) {
    return true;
  }
  // Detect formatted PANs with common separators (e.g., 4111-1111-1111-1111)
  const normalized = value.replace(/[\s-]/g, '');
  return /^\d{13,19}$/.test(normalized);
}

function containsPotentialCvv(value: string, fieldPath: string): boolean {
  if (SAFE_SHORT_NUMERIC_FIELDS.has(fieldPath)) {
    return false;
  }
  // CVV/CVC are typically 3 or 4 digits
  return /^\d{3,4}$/.test(value);
}

function scanForSensitiveData(obj: unknown, currentPath: string, errors: string[]): void {
  if (obj === null || obj === undefined) {
    return;
  }

  if (typeof obj === 'string') {
    if (containsPan(obj)) {
      errors.push(`${currentPath}: contains raw PAN`);
    }
    if (containsPotentialCvv(obj, currentPath)) {
      errors.push(`${currentPath}: contains potential security code`);
    }
    return;
  }

  if (typeof obj === 'object' && !Array.isArray(obj)) {
    for (const [key, value] of Object.entries(obj)) {
      const newPath = currentPath ? `${currentPath}.${key}` : key;
      scanForSensitiveData(value, newPath, errors);
    }
  }
}

// --- Structural validation helpers ---

function validateRequiredField(
  obj: Record<string, unknown>,
  field: string,
  expectedType: 'string' | 'number' | 'object',
  errors: string[]
): unknown {
  if (!(field in obj)) {
    errors.push(`${field}: required`);
    return undefined;
  }

  const value = obj[field];

  if (value === null) {
    errors.push(`${field}: cannot be null`);
    return undefined;
  }

  if (expectedType === 'string' && typeof value !== 'string') {
    errors.push(`${field}: must be a string`);
    return undefined;
  }

  if (expectedType === 'number' && typeof value !== 'number') {
    errors.push(`${field}: must be a number`);
    return undefined;
  }

  if (expectedType === 'object' && (typeof value !== 'object' || Array.isArray(value))) {
    errors.push(`${field}: must be an object`);
    return undefined;
  }

  return value;
}

function validatePaymentMethod(pm: unknown, errors: string[]): void {
  if (pm === null || pm === undefined) {
    errors.push('payment_method: required');
    return;
  }

  if (typeof pm !== 'object' || Array.isArray(pm)) {
    errors.push('payment_method: must be an object');
    return;
  }

  const pmObj = pm as Record<string, unknown>;

  const token = validateRequiredField(pmObj, 'token', 'string', errors);
  const brand = validateRequiredField(pmObj, 'brand', 'string', errors);
  const last4 = validateRequiredField(pmObj, 'last4', 'string', errors);
  const expMonth = validateRequiredField(pmObj, 'exp_month', 'number', errors);
  const expYear = validateRequiredField(pmObj, 'exp_year', 'number', errors);

  if (token !== undefined && !isValidToken(token as string)) {
    errors.push('payment_method.token: invalid format');
  }

  if (brand !== undefined && !VALID_CARD_BRANDS.includes(brand as string)) {
    errors.push('payment_method.brand: unsupported brand');
  }

  if (last4 !== undefined && !isValidLast4(last4 as string)) {
    errors.push('payment_method.last4: must be exactly 4 digits');
  }

  if (expMonth !== undefined) {
    const month = expMonth as number;
    if (!Number.isInteger(month) || month < 1 || month > 12) {
      errors.push('payment_method.exp_month: must be 1-12');
    }
  }

  if (expYear !== undefined) {
    const year = expYear as number;
    if (!Number.isInteger(year) || year < 2000) {
      errors.push('payment_method.exp_year: invalid year');
    }
  }

  for (const key of Object.keys(pmObj)) {
    if (!ALLOWED_PAYMENT_METHOD_FIELDS.includes(key)) {
      errors.push(`payment_method.${key}: unexpected field`);
    }
  }
}

function validateBillingAddress(addr: unknown, errors: string[]): Record<string, unknown> | null {
  if (addr === null || addr === undefined) {
    errors.push('billing_address: required');
    return null;
  }

  if (typeof addr !== 'object' || Array.isArray(addr)) {
    errors.push('billing_address: must be an object');
    return null;
  }

  const addrObj = addr as Record<string, unknown>;

  validateRequiredField(addrObj, 'name', 'string', errors);
  validateRequiredField(addrObj, 'line1', 'string', errors);
  validateRequiredField(addrObj, 'city', 'string', errors);
  validateRequiredField(addrObj, 'state', 'string', errors);
  validateRequiredField(addrObj, 'postal_code', 'string', errors);
  validateRequiredField(addrObj, 'country', 'string', errors);

  const line2 = addrObj.line2;
  if (line2 !== undefined && line2 !== null && typeof line2 !== 'string') {
    errors.push('billing_address.line2: must be a string');
  }

  if (typeof addrObj.country === 'string' && !isValidCountryCode(addrObj.country)) {
    errors.push('billing_address.country: invalid ISO 3166-1 alpha-2 code');
  }

  for (const key of Object.keys(addrObj)) {
    if (!ALLOWED_ADDRESS_FIELDS.includes(key)) {
      errors.push(`billing_address.${key}: unexpected field`);
    }
  }

  return addrObj;
}

function validateMetadata(metadata: unknown, errors: string[]): void {
  if (metadata === undefined || metadata === null) {
    return;
  }

  if (typeof metadata !== 'object' || Array.isArray(metadata)) {
    errors.push('metadata: must be an object');
    return;
  }

  const metaObj = metadata as Record<string, unknown>;
  const entries = Object.entries(metaObj);

  if (entries.length > 20) {
    errors.push('metadata: max 20 entries allowed');
  }

  for (const [key, value] of entries) {
    if (typeof value !== 'string') {
      errors.push(`metadata.${key}: value must be a string`);
    } else if (value.length > 500) {
      errors.push(`metadata.${key}: value exceeds 500 characters`);
    }
  }
}

// --- Cross-field validation ---

function validateCrossField(payload: Record<string, unknown>, clock: Clock, errors: string[]): void {
  const pm = payload.payment_method as Record<string, unknown> | undefined;
  if (pm && typeof pm.exp_year === 'number') {
    const currentYear = clock.getCurrentYear();
    if (pm.exp_year < currentYear) {
      errors.push('payment_method.exp_year: must be current year or future');
    }
  }

  const addr = payload.billing_address as Record<string, unknown> | undefined;
  if (addr && typeof addr.country === 'string') {
    const country = addr.country;
    const state = typeof addr.state === 'string' ? addr.state : undefined;
    const postalCode = typeof addr.postal_code === 'string' ? addr.postal_code : undefined;

    if (country === 'US') {
      if (state !== undefined && !isValidUsState(state)) {
        errors.push('billing_address.state: must be 2-letter code for US');
      }
      if (postalCode !== undefined && !isValidUsPostalCode(postalCode)) {
        errors.push('billing_address.postal_code: invalid format');
      }
    } else {
      if (state !== undefined && state.length > 32) {
        errors.push('billing_address.state: max 32 characters for non-US');
      }
      if (postalCode !== undefined && !isValidNonUsPostalCode(postalCode)) {
        errors.push('billing_address.postal_code: invalid format');
      }
    }
  }
}

// --- Main entry point ---

export function validateTokenizedPayment(payload: unknown, clock: Clock): ValidationResult {
  const errors: string[] = [];

  // Step 1: Scan for sensitive data (PAN, CVV) anywhere in the payload
  scanForSensitiveData(payload, '', errors);

  // Step 2: Validate payload is an object
  if (payload === null || payload === undefined) {
    errors.push('payload: required');
    return { valid: false, errors };
  }

  if (typeof payload !== 'object' || Array.isArray(payload)) {
    errors.push('payload: must be an object');
    return { valid: false, errors };
  }

  const payloadObj = payload as Record<string, unknown>;

  // Step 3: Structural validation
  const requestId = validateRequiredField(payloadObj, 'request_id', 'string', errors);
  const merchantId = validateRequiredField(payloadObj, 'merchant_id', 'string', errors);
  const idempotencyKey = validateRequiredField(payloadObj, 'idempotency_key', 'string', errors);

  if (requestId !== undefined && !isValidPrefixedUuid(requestId as string)) {
    errors.push('request_id: invalid UUID format');
  }

  if (merchantId !== undefined && !isValidPrefixedUuid(merchantId as string)) {
    errors.push('merchant_id: invalid UUID format');
  }

  if (idempotencyKey !== undefined && !isValidIdempotencyKey(idempotencyKey as string)) {
    errors.push('idempotency_key: must be 16-64 alphanumeric/hyphen characters');
  }

  validatePaymentMethod(payloadObj.payment_method, errors);
  validateBillingAddress(payloadObj.billing_address, errors);
  validateMetadata(payloadObj.metadata, errors);

  for (const key of Object.keys(payloadObj)) {
    if (!ALLOWED_TOP_LEVEL_FIELDS.includes(key)) {
      errors.push(`${key}: unexpected field`);
    }
  }

  // Step 4: Cross-field validation
  validateCrossField(payloadObj, clock, errors);

  return {
    valid: errors.length === 0,
    errors,
  };
}
