```typescript
import { isValidUuid } from '../utils/validation';

export interface Clock {
  getCurrentYear: () => number;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const ALLOWED_BRANDS = new Set(['visa', 'mastercard', 'amex', 'discover']);
const PAN_PATTERN = /\d{13,19}/;
const CVV_PATTERN = /^\d{3,4}$/;
const TOKEN_PATTERN = /^tok_[a-zA-Z0-9]{16,32}$/;
const LAST4_PATTERN = /^\d{4}$/;
const US_POSTAL_PATTERN = /^\d{5}$|^\d{5}-\d{4}$/;
const NON_US_POSTAL_PATTERN = /^[a-zA-Z0-9]{2,10}$/;
const COUNTRY_PATTERN = /^[A-Z]{2}$/i;
const US_STATE_PATTERN = /^[A-Z]{2}$/i;
const IDEMPOTENCY_KEY_PATTERN = /^[a-zA-Z0-9-]{16,64}$/;

function scanForSensitiveData(value: any, path: string, errors: string[]): void {
  if (typeof value === 'string') {
    const isTokenField = path === 'payment_method.token';
    const isLast4Field = path === 'payment_method.last4';
    const isPostalCodeField = path === 'billing_address.postal_code';
    const isExpYearField = path === 'payment_method.exp_year';

    // PAN detection
    if (!isTokenField || !value.startsWith('tok_')) {
      if (PAN_PATTERN.test(value)) {
        errors.push(`${path}: contains potential PAN data`);
      }
    }

    // CVV detection
    if (!isLast4Field && !isPostalCodeField && !isExpYearField) {
      if (CVV_PATTERN.test(value)) {
        errors.push(`${path}: contains potential security code`);
      }
    }
  } else if (typeof value === 'number') {
    const isExpYearField = path === 'payment_method.exp_year';
    const isExpMonthField = path === 'payment_method.exp_month';

    const strValue = String(value);

    // PAN detection for numbers
    if (PAN_PATTERN.test(strValue)) {
      errors.push(`${path}: contains potential PAN data`);
    }

    // CVV detection for numbers
    if (!isExpYearField && !isExpMonthField) {
      if (CVV_PATTERN.test(strValue)) {
        errors.push(`${path}: contains potential security code`);
      }
    }
  } else if (Array.isArray(value)) {
    value.forEach((item, index) => {
      scanForSensitiveData(item, `${path}[${index}]`, errors);
    });
  } else if (value !== null && typeof value === 'object') {
    Object.entries(value).forEach(([key, val]) => {
      const newPath = path ? `${path}.${key}` : key;
      scanForSensitiveData(val, newPath, errors);
    });
  }
}

function addError(errors: string[], path: string, message: string): void {
  errors.push(`${path}: ${message}`);
}

function validateRequiredString(value: any, path: string, errors: string[]): string | undefined {
  if (value === undefined) {
    addError(errors, path, 'required');
    return undefined;
  }
  if (value === null) {
    addError(errors, path, 'must be a string');
    return undefined;
  }
  if (typeof value !== 'string') {
    addError(errors, path, 'must be a string');
    return undefined;
  }
  return value;
}

function validateOptionalString(value: any, path: string, errors: string[]): string | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== 'string') {
    addError(errors, path, 'must be a string');
    return undefined;
  }
  return value;
}

function validateRequiredNumber(value: any, path: string, errors: string[]): number | undefined {
  if (value === undefined) {
    addError(errors, path, 'required');
    return undefined;
  }
  if (value === null) {
    addError(errors, path, 'must be a number');
    return undefined;
  }
  if (typeof value !== 'number' || Number.isNaN(value) || !Number.isFinite(value)) {
    addError(errors, path, 'must be a number');
    return undefined;
  }
  if (!Number.isInteger(value)) {
    addError(errors, path, 'must be an integer');
    return undefined;
  }
  return value;
}

function validateRequiredObject(value: any, path: string, errors: string[]): Record<string, any> | undefined {
  if (value === undefined) {
    addError(errors, path, 'required');
    return undefined;
  }
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    addError(errors, path, 'must be an object');
    return undefined;
  }
  return value;
}

function validateRequestId(value: any, errors: string[]): void {
  const str = validateRequiredString(value, 'request_id', errors);
  if (str !== undefined && !isValidUuid(str)) {
    addError(errors, 'request_id', 'invalid UUID format');
  }
}

function validateMerchantId(value: any, errors: string[]): void {
  const str = validateRequiredString(value, 'merchant_id', errors);
  if (str !== undefined && !isValidUuid(str)) {
    addError(errors, 'merchant_id', 'invalid UUID format');
  }
}

function validateIdempotencyKey(value: any, errors: string[]): void {
  const str = validateRequiredString(value, 'idempotency_key', errors);
  if (str !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(str)) {
    addError(errors, 'idempotency_key', 'must be 16-64 alphanumeric or hyphen characters');
  }
}

function validatePaymentMethod(value: any, clock: Clock, errors: string[]): void {
  const obj = validateRequiredObject(value, 'payment_method', errors);
  if (obj === undefined) return;

  // Check for extra fields
  const allowedFields = new Set(['token', 'brand', 'last4', 'exp_month', 'exp_year']);
  Object.keys(obj).forEach(key => {
    if (!allowedFields.has(key)) {
      addError(errors, `payment_method.${key}`, 'unknown field');
    }
  });

  // token
  const token = validateRequiredString(obj.token, 'payment_method.token', errors);
  if (token !== undefined && !TOKEN_PATTERN.test(token)) {
    addError(errors, 'payment_method.token', 'invalid format');
  }

  // brand
  const brand = validateRequiredString(obj.brand, 'payment_method.brand', errors);
  if (brand !== undefined && !ALLOWED_BRANDS.has(brand)) {
    addError(errors, 'payment_method.brand', 'unsupported brand');
  }

  // last4
  const last4 = validateRequiredString(obj.last4, 'payment_method.last4', errors);
  if (last4 !== undefined && !LAST4_PATTERN.test(last4)) {
    addError(errors, 'payment_method.last4', 'must be exactly 4 digits');
  }

  // exp_month
  const expMonth = validateRequiredNumber(obj.exp_month, 'payment_method.exp_month', errors);
  if (expMonth !== undefined && (expMonth < 1 || expMonth > 12)) {
    addError(errors, 'payment_method.exp_month', 'must be between 1 and 12');
  }

  // exp_year
  const expYear = validateRequiredNumber(obj.exp_year, 'payment_method.exp_year', errors);
  if (expYear !== undefined) {
    const currentYear = clock.getCurrentYear();
    if (expYear < currentYear) {
      addError(errors, 'payment_method.exp_year', 'must be current year or future');
    }
  }
}

function validateBillingAddress(value: any, errors: string[]): void {
  const obj = validateRequiredObject(value, 'billing_address', errors);
  if (obj === undefined) return;

  // Check for extra fields
  const allowedFields = new Set(['name', 'line1', 'line2', 'city', 'state', 'postal_code', 'country']);
  Object.keys(obj).forEach(key => {
    if (!allowedFields.has(key)) {
      addError(errors, `billing_address.${key}`, 'unknown field');
    }
  });

  // name
  validateRequiredString(obj.name, 'billing_address.name', errors);

  // line1
  validateRequiredString(obj.line1, 'billing_address.line1', errors);

  // line2 (optional)
  validateOptionalString(obj.line2, 'billing_address.line2', errors);

  // city
  validateRequiredString(obj.city, 'billing_address.city', errors);

  // country
  const country = validateRequiredString(obj.country, 'billing_address.country', errors);
  let isUS = false;
  if (country !== undefined) {
    if (!COUNTRY_PATTERN.test(country)) {
      addError(errors, 'billing_address.country', 'must be ISO 3166-1 alpha-2');
    } else if (country.toUpperCase() === 'US') {
      isUS = true;
    }
  }

  // state
  const state = validateRequiredString(obj.state, 'billing_address.state', errors);
  if (state !== undefined) {
    if (isUS) {
      if (!US_STATE_PATTERN.test(state)) {
        addError(errors, 'billing_address.state', 'must be 2-letter code for US addresses');
      }
    } else {
      if (state.length > 32) {
        addError(errors, 'billing_address.state', 'must be at most 32 characters');
      }
    }
  }

  // postal_code
  const postalCode = validateRequiredString(obj.postal_code, 'billing_address.postal_code', errors);
  if (postalCode !== undefined) {
    if (isUS) {
      if (!US_POSTAL_PATTERN.test(postalCode)) {
        addError(errors, 'billing_address.postal_code', 'invalid format');
      }
    } else {
      if (!NON_US_POSTAL_PATTERN.test(postalCode)) {
        addError(errors, 'billing_address.postal_code', 'invalid format');
      }
    }
  }
}

function validateMetadata(value: any, errors: string[]): void {
  if (value === undefined || value === null) {
    return;
